export function mountControls(container,engine,onChange=()=>{},{regionPicker=false}={}){
  const setLabel=(node,label)=>{if(window.GCD_I18N)window.GCD_I18N.write(node,label);else node.textContent=label;};
  container.innerHTML=(window.GCD_I18N?.fragment || (s=>s))(`<div class="control-row"><label>Paper<select name="paper"><option>A4</option><option>A3</option><option>A5</option><option>Letter</option><option>Legal</option><option value="custom">Custom size</option></select></label><label>Orientation<select name="orientation"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select></label></div>
  <div class="control-row" data-custom hidden><label>Units<select name="units"><option value="mm">mm</option><option value="in">inches</option></select></label><label>Width<input name="width" type="number" value="210" step="0.01"></label><label>Height<input name="height" type="number" value="297" step="0.01"></label></div>
  <details><summary>Page settings <span>Margins, scale &amp; output</span></summary><div class="control-row"><label>Margin preset<select name="marginPreset"><option value="10">Comfortable · 10 mm</option><option value="0">None</option><option value="20">Spacious · 20 mm</option><option value="custom">Custom</option></select></label><label class="checkbox"><input type="checkbox" name="linked" checked>Link all margins</label></div><div class="margins">${['top','right','bottom','left'].map(side=>`<label><span>${side.charAt(0).toUpperCase()+side.slice(1)}</span> (mm)<input name="${side}" type="number" min="0" max="50" step="0.5" value="10"></label>`).join('')}</div>
  <div class="control-row" data-capability="scale,layout"><label>Scale<select name="scale"><option value="1">100%</option><option value="0.5">50%</option><option value="0.75">75%</option><option value="1.25">125%</option><option value="1.5">150%</option></select></label><label>Layout<select name="layout"><option value="paged">Paginated PDF</option><option value="long">One long page</option></select></label></div>
  <label>PDF pages <input name="ranges" placeholder="All pages, or 1-3, 5" maxlength="200"></label><p class="help" data-capability="systemPrint">Page ranges apply to PDF download. For system printing, choose pages in the print dialog.</p>
  <label class="checkbox" data-capability="background"><input name="background" type="checkbox" checked>Keep background colors and images</label>
  <div data-capability="headers"><label class="checkbox"><input name="headers" type="checkbox">Add headers and footers (12 mm minimum)</label><label>Header/footer template<select name="template"><option value="title-page">Document title + page numbers</option><option value="source-date">Source URL + date + page numbers</option><option value="page-only">Page numbers only</option><option value="custom">Custom text</option></select></label><div data-custom-header hidden><label>Custom text<input name="headerTemplate" maxlength="200" placeholder="Report {title} | Page {page} of {total} · {date}"></label><p class="help">Use {title}, {url}, {date}, {page} and {total}. Text before the bar | becomes the header, after it becomes the footer.</p></div></div></details>
  <details data-capability="content,waitFor,media,preferCSSPageSize,hideFixed,hideNavigation,preScroll,loading"><summary>Webpage settings <span>Content &amp; loading</span></summary><label>Content<select name="content"><option value="full">Full page</option><option value="article">Main article</option><option value="selection">Selected element (CSS selector)</option></select></label><label data-selector hidden>Element selector<input name="selector" placeholder="article, #report or .invoice" maxlength="300"></label>
  <div class="control-row"><label>Styles<select name="media"><option value="print">Print stylesheet</option><option value="screen">Screen stylesheet</option></select></label><label data-capability="viewport">Page viewport<select name="viewport"><option value="desktop">Desktop · 1280 px</option><option value="mobile">Mobile · 390 px</option></select></label></div>
  <label class="checkbox"><input name="cssPaper" type="checkbox">Use the webpage's own paper size (overrides my paper settings)</label><label class="checkbox"><input name="fixed" type="checkbox">Hide sticky and fixed elements</label><label class="checkbox"><input name="navigation" type="checkbox">Hide navigation</label><label class="checkbox"><input name="scroll" type="checkbox">Scroll to load images (bounded)</label><label>Resource loading<select name="loading"><option value="balanced">Balanced · up to 5 seconds</option><option value="fast">Fast · up to 2 seconds</option><option value="patient">Patient · up to 10 seconds</option></select></label>
  <label class="checkbox" data-capability="javascript"><input name="javascript" type="checkbox" checked>Load JavaScript (turn off for a snapshot of the raw document)</label>
  <label data-capability="waitFor">Wait for this element<select name="waitForMode"><option value="">Do not wait</option><option value="selector">Wait for a selector to appear</option></select></label>
  <label data-capability="waitFor" data-wait-for hidden>Element selector<input name="waitFor" maxlength="300" placeholder="article.ready, #report or .invoice"></label>
  <p class="help" data-capability="waitFor">Waiting is useful for pages that render their content late. Disabling JavaScript also disables long pages, content selection and page cleanup.</p></details>
  <details><summary>My presets <span>Settings only, never content</span></summary><div class="control-row"><label>Saved preset<select name="presets"><option value="">Choose…</option></select></label><label>Preset name<input name="presetName" maxlength="40" placeholder="Weekly report"></label></div><div class="button-row"><button type="button" data-save>Save preset</button><button type="button" data-rename>Rename selected</button><button type="button" data-delete>Delete selected</button><button type="button" data-default>Set as default</button><button type="button" data-last>Use last settings</button><button type="button" data-reset>Reset settings</button><button type="button" data-export>Export presets</button><button type="button" data-import>Import presets</button><input type="file" data-import-file accept="application/json,.json" hidden></div><p class="help" data-preset-status role="status"></p></details>`);
  const field=name=>container.querySelector(`[name="${name}"]`);
  const modes=document.createElement('div');modes.className='content-modes';modes.dataset.capability='content';modes.setAttribute('role','group');modes.setAttribute('aria-label',(window.GCD_I18N ? window.GCD_I18N.text(window.GCD_I18N?.text('Content')||'Content') : window.GCD_I18N?.text('Content')||'Content'));
  for(const [value,label] of [['full','Full page'],['article','Main article'],['selection','Pick content']]){
    const button=document.createElement('button');button.type='button';button.dataset.contentMode=value;setLabel(button,label);
    button.onclick=()=>{if(value==='selection'&&(currentEngine==='extension'||currentEngine==='server'&&regionPicker)){window.dispatchEvent(new Event(currentEngine==='extension'?'gcd:pick-content':'gcd:pick-web-region'));return;}field('content').value=value;field('content').dispatchEvent(new Event('change',{bubbles:true}));if(value==='selection'){field('selector').closest('details').open=true;field('selector').focus();}};modes.append(button);
  }
  const selectionHelp=document.createElement('p');selectionHelp.className='help';selectionHelp.dataset.selectionHelp='';
  const selectionLink=document.createElement('a');selectionLink.href='extensions.html';
  setLabel(selectionLink,'Select directly on the webpage with the Chrome or Edge extension');
  selectionHelp.append(selectionLink);
  container.prepend(modes,selectionHelp);
  const manualSelector=document.createElement('button');manualSelector.type='button';setLabel(manualSelector,'Advanced: CSS selector');
  manualSelector.onclick=()=>{field('content').value='selection';field('selector').value='';update();onChange();field('selector').focus();};
  field('selector').closest('label').before(manualSelector);
  let currentEngine=engine,presets={},defaultPreset='';
  function refreshPresets(){const select=field('presets');select.replaceChildren(new Option(window.GCD_I18N?.text('Choose…')||'Choose…',''));Object.keys(presets).slice(0,20).forEach(name=>select.add(new Option(name,name)));}
  function snapshot(){return Object.fromEntries([...container.querySelectorAll('input,select')].filter(el=>el.name&&!['presets','presetName'].includes(el.name)).map(el=>[el.name,el.type==='checkbox'?el.checked:el.value]));}
  const defaults=snapshot();let previousUnit='mm';
  function validName(name){return typeof name==='string'&&!!name.trim()&&name.length<=40&&!['__proto__','constructor','prototype'].includes(name);}
  function cleanPreset(values){if(!values||typeof values!=='object'||Array.isArray(values))throw Error('Invalid preset settings.');const clean={...defaults};for(const [name,value] of Object.entries(values)){if(!Object.hasOwn(defaults,name))continue;const el=field(name);if(el.type==='checkbox'){if(typeof value!=='boolean')throw Error('Invalid preset settings.');}else if(el.tagName==='SELECT'){if(![...el.options].some(option=>option.value===value))throw Error('Invalid preset settings.');}else if(el.type==='number'){if(!Number.isFinite(Number(value))||String(value).length>20)throw Error('Invalid preset settings.');const number=Number(value);if(el.min!==''&&number<Number(el.min)||el.max!==''&&number>Number(el.max))throw Error('Invalid preset settings.');}else if(typeof value!=='string'||value.length>Math.min(el.maxLength>0?el.maxLength:200,200))throw Error('Invalid preset settings.');clean[name]=value;}clean.selector='';clean.waitFor='';clean.waitForMode='';if(clean.content==='selection')clean.content='full';return clean;}
  function saveStore(){localStorage.setItem('gcd-layout-presets-v3',JSON.stringify({version:3,presets,defaultPreset}));}
  try{const saved=JSON.parse(localStorage.getItem('gcd-layout-presets-v3')||'null');const legacy=JSON.parse(localStorage.getItem('gcd-layout-presets-v2')||'{}');const source=saved?.version===3?saved.presets:legacy;if(source&&typeof source==='object'&&!Array.isArray(source)){for(const [name,values] of Object.entries(source).slice(0,20)){if(!validName(name))continue;try{presets[name]=cleanPreset(values);}catch{}}}if(saved?.version===3&&presets[saved.defaultPreset])defaultPreset=saved.defaultPreset;if(!saved)saveStore();}catch{}
  function remember(){try{read();const values=snapshot();values.selector='';if(values.content==='selection')values.content='full';localStorage.setItem('gcd-layout-recent-v2',JSON.stringify(values));}catch{}}
  function apply(values,{rememberChange=true}={}){Object.entries(values).forEach(([name,value])=>{const el=field(name);if(!el)return;if(el.type==='checkbox')el.checked=!!value;else el.value=value;});previousUnit=field('units').value;update();if(rememberChange)remember();onChange();}
  // E1-3: visibility comes from the engine capability matrix, never from hardcoded engine lists.
  function update(){const selectionLabel=currentEngine==='server'&&!regionPicker?'Advanced: CSS selector':'Pick content';setLabel(modes.querySelector('[data-content-mode="selection"]'),selectionLabel);selectionHelp.hidden=currentEngine!=='server';manualSelector.hidden=currentEngine!=='server';const supported=capability=>ConversionOptions.supports(currentEngine,capability);container.querySelectorAll('[data-capability]').forEach(el=>el.hidden=!el.dataset.capability.split(',').some(supported));modes.querySelectorAll('button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.contentMode===field('content').value)));container.querySelector('[data-custom]').hidden=field('paper').value!=='custom';container.querySelector('[data-selector]').hidden=field('content').value!=='selection'||currentEngine==='server'&&field('selector').value==='#gcd-visual-region';container.querySelector('[data-custom-header]').hidden=field('template').value!=='custom';container.querySelector('[data-wait-for]').hidden=field('waitForMode').value!=='selector';}
  container.addEventListener('change',event=>{
    const el=event.target;
    if(el.name==='units'){const unit=el.value,factor=unit==='in'?1/25.4:25.4;if(unit!==previousUnit)['width','height'].forEach(n=>field(n).value=(Number(field(n).value)*factor).toFixed(3));previousUnit=unit;}
    if(el.name==='marginPreset'&&el.value!=='custom')['top','right','bottom','left'].forEach(n=>field(n).value=el.value);
    if(['top','right','bottom','left'].includes(el.name)){field('marginPreset').value='custom';if(field('linked').checked)['top','right','bottom','left'].forEach(n=>field(n).value=el.value);}
    if(el.name==='headers'&&el.checked){['top','bottom'].forEach(n=>field(n).value=Math.max(12,Number(field(n).value)));field('marginPreset').value='custom';field('linked').checked=false;}
    if(el.name==='presets'&&presets[el.value])return apply(presets[el.value]);
    update();if(!['presets','presetName'].includes(el.name)){remember();onChange();}
  });
  container.addEventListener('input',event=>{if(!['presetName'].includes(event.target.name))onChange();});
  const message=value=>container.querySelector('[data-preset-status]').textContent=window.GCD_I18N?.text(value)||value;
  container.querySelector('[data-save]').onclick=()=>{const name=field('presetName').value.trim();if(!name)return message('Enter a preset name.');if(!validName(name))return message('Choose another name.');try{read();if(!presets[name]&&Object.keys(presets).length>=20)throw Error('Keep at most 20 presets.');presets[name]=cleanPreset(snapshot());saveStore();refreshPresets();field('presets').value=name;message('Preset saved on this device.');}catch(error){message(error.message);}};
  container.querySelector('[data-rename]').onclick=()=>{const old=field('presets').value,name=field('presetName').value.trim();if(!presets[old]||!validName(name)||presets[name]&&name!==old)return message('Choose another name.');presets[name]=presets[old];if(name!==old)delete presets[old];if(defaultPreset===old)defaultPreset=name;try{saveStore();refreshPresets();field('presets').value=name;message('Preset saved on this device.');}catch{message('Storage is unavailable.');}};
  container.querySelector('[data-delete]').onclick=()=>{const name=field('presets').value;if(!presets[name])return;delete presets[name];if(defaultPreset===name)defaultPreset='';try{saveStore();refreshPresets();message('Preset removed.');}catch{message('Storage is unavailable.');}};
  container.querySelector('[data-default]').onclick=()=>{const name=field('presets').value;if(!presets[name])return message('Choose a preset first.');defaultPreset=name;try{saveStore();message('Preset saved on this device.');}catch{message('Storage is unavailable.');}};
  container.querySelector('[data-last]').onclick=()=>{defaultPreset='';try{saveStore();const recent=JSON.parse(localStorage.getItem('gcd-layout-recent-v2')||'null');if(recent)apply(cleanPreset(recent));message('Using your last settings.');}catch(error){message(error.message);}};
  container.querySelector('[data-export]').onclick=()=>{try{const blob=new Blob([JSON.stringify({version:3,presets,defaultPreset},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='goodconvertpdf-presets.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(error){message(error.message);}};
  const importFile=container.querySelector('[data-import-file]');container.querySelector('[data-import]').onclick=()=>importFile.click();importFile.onchange=async()=>{const file=importFile.files?.[0];importFile.value='';if(!file)return;try{if(file.size>128*1024)throw Error('Preset file is too large.');const data=JSON.parse(await file.text());if(data?.version!==3||!data.presets||typeof data.presets!=='object'||Array.isArray(data.presets))throw Error('Unsupported preset file.');const incoming=Object.entries(data.presets);if(incoming.length>20||Object.keys(presets).length+incoming.length>20)throw Error('Keep at most 20 presets.');const next={...presets};for(const [name,values] of incoming){if(!validName(name)||Object.hasOwn(next,name))throw Error('Preset name already exists or is invalid.');next[name]=cleanPreset(values);}presets=next;saveStore();refreshPresets();message('Preset saved on this device.');}catch(error){message(error.message);}};
  container.querySelector('[data-reset]').onclick=()=>apply(defaults);
  function read(){const web=['server','extension'].includes(currentEngine);return ConversionOptions.normalize({paper:field('paper').value==='custom'?{mode:'custom',widthMm:Number(field('width').value)*(field('units').value==='in'?25.4:1),heightMm:Number(field('height').value)*(field('units').value==='in'?25.4:1)}:{mode:'preset',format:field('paper').value},orientation:field('orientation').value,marginsMm:Object.fromEntries(['top','right','bottom','left'].map(n=>[n,Number(field(n).value)])),scale:web?Number(field('scale').value):1,layout:web?field('layout').value:'paged',pageRanges:field('ranges').value,printBackground:currentEngine==='images'?true:field('background').checked,headerFooter:{enabled:web&&field('headers').checked,templateId:field('template').value,template:field('headerTemplate').value},contentMode:web?field('content').value:'full',selector:web?field('selector').value:'',javascript:!(currentEngine==='server')||field('javascript').checked,waitFor:field('waitForMode').value==='selector'?field('waitFor').value:'',media:web?field('media').value:'print',viewport:currentEngine==='server'?field('viewport').value:'desktop',preferCSSPageSize:web&&field('cssPaper').checked,hideFixed:web&&field('fixed').checked,hideNavigation:web&&field('navigation').checked,loading:{preset:web?field('loading').value:'balanced',preScroll:web&&field('scroll').checked}});}
  window.addEventListener('languagechange',()=>{field('presets').options[0].textContent=window.GCD_I18N?.text('Choose…')||'Choose…';});
  refreshPresets();update();
  try{const recent=JSON.parse(localStorage.getItem('gcd-layout-recent-v2')||'null');if(defaultPreset&&presets[defaultPreset])apply(presets[defaultPreset],{rememberChange:false});else if(recent&&typeof recent==='object'&&!Array.isArray(recent))apply(cleanPreset(recent),{rememberChange:false});}catch{}
  return {read,field,apply,snapshot(){return cleanPreset(snapshot());},reset(){apply(defaults);},setEngine(value){currentEngine=value;update();},setSelection(selector){field('content').value='selection';field('selector').value=selector;update();onChange();}};
}
